mapper.select:

WHERE r.deleted = 0

    AND r.batch_id = #{q.batchId}


    AND r.sensor_code = #{q.sensorCode}


    AND r.sample_time >= #{q.startTime}


    AND r.sample_time <= #{q.endTime}


    AND r.db_value >= #{q.dbMin}


    AND r.db_value <= #{q.dbMax}


    AND ae.id IS NULL


    AND ae.id IS NOT NULL


    AND ae.status = #{q.anomalyStatus}

ORDER BY r.sample_time DESC, r.id DESC

SELECT DATE_FORMAT(sample_time, '%Y-%m-%d %H:00') AS time_bucket, ROUND(AVG(db_value), 2) AS avg_db, MAX(db_value) AS max_db, MIN(db_value) AS min_db, COUNT(*) AS sample_count FROM noise_record WHERE deleted = 0
AND sensor_code = #{sensorCode}
AND sample_time >= #{startTime}
AND sample_time <= #{endTime}
GROUP BY time_bucket ORDER BY time_bucket LIMIT 500
